insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-01', '01', 'Developer Environment & Foundations', 'Foundation', 185, NULL, '"Setting up my dev environment the right way" — your terminal/editor config, ESLint+Prettier rules, and why you picked them.**', false, 0);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-01b', '01b', 'TypeScript Mastery', 'Foundation', 80, NULL, 'One TypeScript gotcha you hit and fixed — a real type error, not a tutorial recap.**', false, 1);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-02', '02', 'React + Next.js Core', 'Foundation', 213, NULL, 'A short screen-recording or GIF of your first deployed Next.js page going live on Vercel.**', false, 2);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-03', '03', 'UI System & Styling', 'Foundation', 135, NULL, 'Before/after screenshots of your UI system — component library, dark mode, design tokens.**', false, 3);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-04', '04', 'State, Data Fetching & Advanced React', 'Core', 153, NULL, '"Why I chose TanStack Query + Zustand over Redux" — a real architectural decision with trade-offs.**', false, 4);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-05', '05', 'Backend + Database + Auth', 'Core', 314, NULL, 'Your auth flow diagram (JWT + httpOnly cookies) — one of the most commonly asked-about topics by other learners.**', false, 5);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-06', '06', 'Testing + CI/CD + Deployment', 'Core', 155, 'A', 'Your green CI badge, first time all tests + Docker build pass in GitHub Actions.**', false, 6);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-06b', '06b', 'React Native (Mobile)', 'Core', 111, 'A2', NULL, false, 7);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-07', '07', 'API Documentation & Developer Tooling', 'Core', 71, 'B', 'Your OpenAPI/Swagger docs page — link it, don''t just say you have API docs.**', false, 8);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-08', '08', 'DSA & Interview Preparation', 'Core', 331, '★1', 'Skip public posting this phase — DSA grind isn''t a visibility play. Log progress privately (see notes doc).**', true, 9);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-09', '09', 'Caching + Email + Payments', 'Advanced', 98, NULL, '"I integrated Razorpay and here''s what nobody tells you about test mode" — a real, specific gotcha post.**', false, 10);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-10', '10', 'Monitoring & Analytics', 'Advanced', 103, 'C', 'A screenshot of your PostHog/Sentry dashboard showing real usage or error data from ClientSync.**', false, 11);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-11', '11', 'Real-Time + Search + PostgreSQL Internals', 'Advanced', 164, '★2', 'A short demo of real-time features (WebSockets/SSE) working in ClientSync.**', false, 12);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-12', '12', 'AI/RAG + Production AI Patterns', 'Advanced', 207, 'D', 'Your RAG pipeline or AI feature — show the actual output, not just "I added AI."**', false, 13);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-13', '13', 'Advanced Browser APIs + Collaboration', 'Advanced', 137, NULL, 'A demo of real-time collaboration (Yjs) — two cursors editing the same doc live.**', false, 14);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-14', '14', 'Load Testing + Security Deep Dive', 'Advanced', 89, NULL, '"I ran a load test on my own app and here''s what broke" — an honest post about a real weakness you found and fixed.**', false, 15);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-15', '15', 'Build Tooling + CSS-in-JS', 'Advanced', 44, NULL, 'Skip public posting — build tooling changes aren''t visible or interesting to an outside audience.**', true, 16);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-16', '16', 'Infrastructure', 'Expert', 175, NULL, 'Your infrastructure diagram — Terraform + Kubernetes setup, even a simple one.**', false, 17);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-17', '17', 'Architectural Patterns', 'Expert', 178, '3', '"Why I used the Saga pattern instead of a distributed transaction" — one architectural pattern, explained simply.**', false, 18);
insert into public.phases (id, phase_number, title, band, estimated_hours, exit_point_code, build_in_public_prompt, skip_build_in_public, order_index) values ('phase-18', '18', 'Engineering Craft + Package Publishing', 'Expert', 62, NULL, 'Your first published npm package, however small.**', false, 19);
